mapper.select:
SELECT A.ALLOW_NM AS ITEM_NM, I.AMT, I.RMK
  FROM TB_PAY_ITEM I
  JOIN TB_ALLOW A ON A.ALLOW_CD = I.ITEM_CD
 WHERE I.PAY_YM = #{PAY_YM}
   AND I.EMP_NO = #{EMP_NO}
   AND I.ITEM_TYPE = 'A'

SELECT I.ITEM_CD AS ITEM_NM, I.AMT
  FROM TB_PAY_ITEM I
 WHERE I.PAY_YM = #{PAY_YM}
   AND I.EMP_NO = #{EMP_NO}
   AND I.ITEM_TYPE = 'D'
